package com.aditya.day13.order; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/orders") public class OrderController{final OrderRepo r;final OrderStateMachine s; OrderController(OrderRepo r,OrderStateMachine s){this.r=r;this.s=s;} record Create(String customerId,String restaurantId,double total){} @PostMapping public FoodOrder create(@RequestBody Create x){FoodOrder o=new FoodOrder();o.setCustomerId(x.customerId());o.setRestaurantId(x.restaurantId());o.setTotal(x.total());return r.save(o);}@GetMapping public List<FoodOrder> all(){return r.findAll();}@GetMapping("/{id}")public FoodOrder get(@PathVariable UUID id){return r.findById(id).orElseThrow();}@PostMapping("/{id}/status/{status}")public FoodOrder move(@PathVariable UUID id,@PathVariable OrderStatus status){FoodOrder o=get(id);s.move(o,status);return r.save(o);}}